  StorePage,
} from './utils/publicRoutes';
import {useStorefrontSeo} from './utils/storefrontSeo';
import { useCustomerCommerce } from './hooks/useCustomerCommerce';
import { reviewPolicyFor } from './services/commerceStorage';

interface ToastState {
  message: string;
  type: 'success' | 'error' | 'info';
}

interface ParcelBuilderState {
  familyProduct: CatalogProduct;
  option: PublicConfigurableParcelOption;
  edit?: { lineId: string; instance: ParcelInstanceSelection };
}

const FAVORITES_STORAGE_KEY = 'nawasrah-store-favorites-v1';
const CATALOG_STALE_TIME_MS = 90_000;
const OFFERS_STALE_TIME_MS = 5 * 60_000;
const STOREFRONT_SETTINGS_STALE_TIME_MS = 10 * 60_000;

const EMPTY_CATALOG_SUMMARY: CatalogSummary = {
  availableProducts: 0,
  availableSalePackages: 0,
  lowStockProducts: 0,
};

type StorefrontResource = 'catalog' | 'offers' | 'settings';

interface CartSnapshotResult {
  items: CartItem[];
}

function readStoredFavorites(): string[] {
  try {
    const storedValue = localStorage.getItem(FAVORITES_STORAGE_KEY);
    if (!storedValue) return [];
    const parsedValue = JSON.parse(storedValue);
    return Array.isArray(parsedValue)
      ? parsedValue.filter((value): value is string => typeof value === 'string')
      : [];
  } catch {
    return [];
  }
}

export function App() {
  const [locationRoute, setLocationRoute] = useState(() =>
    readStoreLocationRoute(window.location)
  );

  useEffect(() => {
    const syncLocation = () => setLocationRoute(readStoreLocationRoute(window.location));
    window.addEventListener('hashchange', syncLocation);
    window.addEventListener('popstate', syncLocation);
    return () => {
      window.removeEventListener('hashchange', syncLocation);
      window.removeEventListener('popstate', syncLocation);
    };
  }, []);

  useEffect(() => {
    if (!locationRoute.receiptToken) return;
    let robots = document.head.querySelector<HTMLMetaElement>('meta[name="robots"]');
    if (!robots) {
      robots = document.createElement('meta');
      robots.name = 'robots';
      document.head.append(robots);
    }
    robots.content = 'noindex, nofollow, noarchive';
  }, [locationRoute.receiptToken]);

  if (locationRoute.receiptToken) return <PublicPosReceiptPage token={locationRoute.receiptToken} />;
  return <StorefrontApp trackingToken={locationRoute.trackingToken} />;
}

function StorefrontApp({ trackingToken }: { trackingToken: string }) {
  const {
    snapshot: commerceSnapshot,
    cartItems,
    cartRecovery: cartStorageRecovery,
    attempt: checkoutAttempt,
    coordinator: checkoutCoordinator,
    setCartItems,
    mutateCart,
    replaceCart,
    resolveCartRecovery,
    refresh: refreshCommerce,
    lastError: commerceStorageError,
  } = useCustomerCommerce();
  const unresolvedCheckoutAttempt = Boolean(
    checkoutAttempt &&
      !['REJECTED', 'ABANDONED'].includes(checkoutAttempt.serverState) &&
      !(checkoutAttempt.serverState === 'SUCCEEDED' && checkoutAttempt.reconciliationState === 'APPLIED')
  );
  const [privacyPolicyOpen, setPrivacyPolicyOpen] = useState(false);
  const [activePage, setActivePage] = useState<StorePage>(
    () => readStoreLocationRoute(window.location).page
  );
  const [products, setProducts] = useState<CatalogProduct[]>([]);
  const [catalogCategories, setCatalogCategories] = useState<
    CatalogCategory[]
  >([]);
  const [catalogBrands, setCatalogBrands] = useState<CatalogFacet[]>([]);
  const [catalogSummary, setCatalogSummary] = useState<CatalogSummary>(
    EMPTY_CATALOG_SUMMARY
  );
  const [catalogTotal, setCatalogTotal] = useState(0);
  const [catalogOffset, setCatalogOffset] = useState(0);
  const [featuredProducts, setFeaturedProducts] = useState({
    newest: [] as CatalogProduct[],
    bestSellers: [] as CatalogProduct[],
    offers: [] as CatalogProduct[],
    lowStock: [] as CatalogProduct[],
  });
  const [featuredProductsLoading, setFeaturedProductsLoading] = useState(true);
  const [featuredProductsError, setFeaturedProductsError] = useState<string | null>(null);
  const [parcelOptionsByFamily, setParcelOptionsByFamily] = useState(
    () => new Map<string, PublicConfigurableParcelOption>()
  );
  const [parcelOptionLoading, setParcelOptionLoading] = useState(false);
  const [parcelBuilder, setParcelBuilder] = useState<ParcelBuilderState | null>(null);
  const [favoriteProductIds, setFavoriteProductIds] = useState<string[]>(
    readStoredFavorites
  );
  const [storefrontOffers, setStorefrontOffers] = useState<StorefrontOffer[]>([]);
  const [offersLoading, setOffersLoading] = useState(true);
  const [offersLoadError, setOffersLoadError] = useState<string | null>(null);
  const [preferredPromotionCode, setPreferredPromotionCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [availabilityFilter, setAvailabilityFilter] =
    useState<CatalogAvailabilityFilter>('all');
  const [sortOption, setSortOption] =
    useState<CatalogSortOption>('recommended');
  const [selectedBrand, setSelectedBrand] = useState('all');
  const [selectedSaleUnit, setSelectedSaleUnit] = useState('all');
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [lastUpdatedAt, setLastUpdatedAt] = useState<Date | null>(null);
  const [isOnline, setIsOnline] = useState(() =>
    typeof navigator === 'undefined' ? true : navigator.onLine
  );
  const [cartOpen, setCartOpen] = useState(false);
  const [isRefreshingCart, setIsRefreshingCart] = useState(false);
  const [isRepeatingLastOrder, setIsRepeatingLastOrder] = useState(false);
  const [cartSnapshotNotice, setCartSnapshotNotice] = useState<string | null>(null);
  const [categoriesOpen, setCategoriesOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [trackingOpen, setTrackingOpen] = useState(false);
  const [assistantOpen, setAssistantOpen] = useState(false);
  const [searchOpenSignal, setSearchOpenSignal] = useState(0);
  const [lastGuestOrder, setLastGuestOrder] = useState<LastGuestOrder | null>(() => readLastGuestOrder(window.localStorage));
  const [selectedProductId, setSelectedProductId] = useState<string | null>(
    null
  );
  const [selectedProductVariantId, setSelectedProductVariantId] = useState<
    string | null
  >(null);
  const [linkedProduct, setLinkedProduct] = useState<CatalogProduct | null>(
    null
  );
  const [toast, setToast] = useState<ToastState | null>(null);
  const [storefrontSettings, setStorefrontSettings] =
    useState<PublicStorefrontSettings>(DEFAULT_STOREFRONT_SETTINGS);
  const [settingsUnavailable, setSettingsUnavailable] = useState(false);
  const [isLoadingStorefrontSettings, setIsLoadingStorefrontSettings] =
    useState(true);
  const lastLoadedAtRef = useRef<Record<StorefrontResource, number>>({
    catalog: 0,
    offers: 0,
    settings: 0,
  });
  const pendingLoadRef = useRef<Record<StorefrontResource, Promise<void> | null>>({
    catalog: null,
    offers: null,
    settings: null,
  });
  const pendingFeaturedProductsRef = useRef<Promise<void> | null>(null);
  const catalogRequestSequenceRef = useRef(0);
  const catalogRequestKeyRef = useRef('');
  const pendingCartSnapshotRef = useRef<{
    key: string;
    promise: Promise<CartSnapshotResult>;
  } | null>(null);
  const pendingRepeatLastOrderRef = useRef<Promise<void> | null>(null);
  const pendingProductLinkRef = useRef<{
    key: string;
    promise: Promise<void>;
  } | null>(null);
  const resolvedProductLinkKeyRef = useRef<string | null>(null);
  const parcelOptionRequestedRef = useRef(new Set<string>());
  const sellableProducts = useMemo(
    () =>
      products.flatMap((product) =>
        product.variants.length > 0 ? product.variants : [product]
      ),
    [products]
  );

  useEffect(() => {
    if (trackingToken) setTrackingOpen(true);
  }, [trackingToken]);

  const showToast = useCallback(
    (message: string, type: ToastState['type'] = 'success') => {
      setToast({ message, type });
      window.setTimeout(() => setToast(null), 2800);
    },
    []
  );

  useEffect(() => {
    if (!commerceStorageError) return;
    showToast(commerceStorageError, 'error');
  }, [commerceStorageError, showToast]);

  const isStale = useCallback(
    (resource: StorefrontResource, staleTimeMs: number) =>
      Date.now() - lastLoadedAtRef.current[resource] >= staleTimeMs,
    []
  );

  const favoritesActive = activePage === 'favorites';

  const catalogQuery = useMemo<PublicCatalogQuery>(
    () => ({
      limit: STOREFRONT_CATALOG_PAGE_SIZE,
      offset: catalogOffset,
      categoryId: selectedCategory === 'all' ? undefined : selectedCategory,
      searchQuery: searchQuery.trim() || undefined,
      availability: availabilityFilter,
      sort: sortOption,
      brandId: selectedBrand === 'all' ? undefined : selectedBrand,
      saleUnitId: selectedSaleUnit === 'all' ? undefined : selectedSaleUnit,
      productIds: favoritesActive ? favoriteProductIds : undefined,
    }),
    [
      availabilityFilter,
      catalogOffset,
      favoriteProductIds,
      favoritesActive,
      searchQuery,
      selectedBrand,
      selectedCategory,
      selectedSaleUnit,
      sortOption,
    ]
  );
  const catalogQueryKey = useMemo(
    () => JSON.stringify(catalogQuery),
    [catalogQuery]
  );

  const loadCatalog = useCallback(
    async (silent = false, force = false) => {
      if (!force && !isStale('catalog', CATALOG_STALE_TIME_MS)) return;
      if (catalogRequestKeyRef.current === catalogQueryKey && pendingLoadRef.current.catalog) {
        return pendingLoadRef.current.catalog;
      }

      const requestSequence = ++catalogRequestSequenceRef.current;
      catalogRequestKeyRef.current = catalogQueryKey;

      const request = (async () => {
        if (silent) setIsRefreshing(true);
        else setIsLoading(true);

        try {
          const catalog = await fetchPublicProductCatalog(catalogQuery);
          if (requestSequence !== catalogRequestSequenceRef.current) return;
          setProducts(catalog.items);
          setCatalogCategories(catalog.categories);
          setCatalogBrands(catalog.brands);
          setCatalogSummary(catalog.summary);
          setCatalogTotal(catalog.total);
          setLoadError(null);
          setLastUpdatedAt(new Date());
          lastLoadedAtRef.current.catalog = Date.now();
        } catch (error) {
          if (requestSequence !== catalogRequestSequenceRef.current) return;
          const message =
            error instanceof Error
              ? error.message
              : 'تعذر تحميل كتالوج الجملة من Supabase.';
          setLoadError(message);
        } finally {
          if (requestSequence === catalogRequestSequenceRef.current) {
            setIsLoading(false);
            setIsRefreshing(false);
          }
        }
      })();

      pendingLoadRef.current.catalog = request;
      try {
        await request;
      } finally {
        if (catalogRequestKeyRef.current === catalogQueryKey) {
          pendingLoadRef.current.catalog = null;
        }
      }
    },
    [catalogQuery, catalogQueryKey, isStale]
  );

  const loadFeaturedProducts = useCallback(async () => {
    if (pendingFeaturedProductsRef.current) return pendingFeaturedProductsRef.current;
    const request = (async () => {
      setFeaturedProductsLoading(true);
      setFeaturedProductsError(null);
      try {
        setFeaturedProducts(await fetchPublicStorefrontMerchandising());
      } catch (error) {
        console.error('[Storefront featured products]', error);
        setFeaturedProducts({ newest: [], bestSellers: [], offers: [], lowStock: [] });
        setFeaturedProductsError('تعذر تحميل الاختيارات المميزة حاليًا.');
      } finally {
        setFeaturedProductsLoading(false);
        pendingFeaturedProductsRef.current = null;
      }
    })();
    pendingFeaturedProductsRef.current = request;
    return request;
  }, []);

  const loadCatalogRef = useRef(loadCatalog);
  useEffect(() => {
    loadCatalogRef.current = loadCatalog;
  }, [loadCatalog]);

  const loadStorefrontSettings = useCallback(
    async (force = false) => {
      if (!force && !isStale('settings', STOREFRONT_SETTINGS_STALE_TIME_MS)) return;
      if (pendingLoadRef.current.settings) return pendingLoadRef.current.settings;

      const request = (async () => {
        setIsLoadingStorefrontSettings(true);
        try {
          setStorefrontSettings(await fetchPublicStorefrontSettings());
          setSettingsUnavailable(false);
          lastLoadedAtRef.current.settings = Date.now();
        } catch (error) {
          console.error('[Storefront settings]', error);
          setSettingsUnavailable(true);
        } finally {
          setIsLoadingStorefrontSettings(false);
        }
      })();

      pendingLoadRef.current.settings = request;
      try {
        await request;
      } finally {
        pendingLoadRef.current.settings = null;
      }
    },
    [isStale]
  );

  const loadStorefrontOffers = useCallback(
    async (force = false) => {
      if (!force && !isStale('offers', OFFERS_STALE_TIME_MS)) return;
      if (pendingLoadRef.current.offers) return pendingLoadRef.current.offers;

      const request = (async () => {
        try {
          setStorefrontOffers(await fetchPublicStorefrontOffers());
          setOffersLoadError(null);
          lastLoadedAtRef.current.offers = Date.now();
        } catch (error) {
          console.error('[Storefront offers]', error);
          setOffersLoadError(
            error instanceof Error ? error.message : 'تعذر تحميل عروض المتجر.'
          );
        } finally {
          setOffersLoading(false);
        }
      })();

      pendingLoadRef.current.offers = request;
      try {
        await request;
      } finally {
        pendingLoadRef.current.offers = null;
      }
    },
    [isStale]
  );

  useEffect(() => {
    void loadStorefrontSettings(true);
    void loadStorefrontOffers(true);
    void loadFeaturedProducts();
    const handleFocus = () => {
      if (document.visibilityState !== 'visible') return;
      void loadCatalogRef.current(true);
      void loadStorefrontOffers();
      void loadStorefrontSettings();
    };
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') handleFocus();
    };
    const handleOnline = () => {
      setIsOnline(true);
      void loadCatalogRef.current(true, true);
      void loadStorefrontSettings(true);
      void loadStorefrontOffers(true);
      void loadFeaturedProducts();
    };
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('focus', handleFocus);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('focus', handleFocus);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [loadFeaturedProducts, loadStorefrontOffers, loadStorefrontSettings]);

  useEffect(() => {
    const delayMs = searchQuery.trim() ? 250 : 0;
    const timer = window.setTimeout(() => {
      void loadCatalog(false, true);
    }, delayMs);
    return () => window.clearTimeout(timer);
  }, [catalogQueryKey, loadCatalog, searchQuery]);

  useEffect(() => {
    if (!lastUpdatedAt) return;

    const elapsedMs = Date.now() - lastUpdatedAt.getTime();
    const delayMs = Math.max(250, CATALOG_STALE_TIME_MS - elapsedMs + 50);
    const refreshTimer = window.setTimeout(() => {
      if (document.visibilityState !== 'visible' || !navigator.onLine) return;
      void loadCatalog(true);
    }, delayMs);

    return () => window.clearTimeout(refreshTimer);
  }, [lastUpdatedAt, loadCatalog]);

  useEffect(() => {
    if (cartStorageRecovery) return;
    if (unresolvedCheckoutAttempt) return;
    if (sellableProducts.length === 0) return;
    setCartItems((currentItems) =>
      reconcileCartPage(currentItems, sellableProducts)
    );
  }, [cartStorageRecovery, sellableProducts, setCartItems, unresolvedCheckoutAttempt]);

  useEffect(() => {
    localStorage.setItem(
      FAVORITES_STORAGE_KEY,
      JSON.stringify(favoriteProductIds)
    );
  }, [favoriteProductIds]);

  useEffect(() => {
    const syncProductFromLocation = () => {
      const route = readStoreLocationRoute(window.location);
      setActivePage(route.page);
      if (!route.productKey) {
        setSelectedProductId(null);
        setSelectedProductVariantId(null);
        setLinkedProduct(null);
        resolvedProductLinkKeyRef.current = null;
        return;
      }

      const productKey = route.productKey;

      const localProductLink = findPublicProductLink(products, productKey);
      if (localProductLink) {
        setLinkedProduct(null);
        setSelectedProductId(localProductLink.family.id);
        setSelectedProductVariantId(
          localProductLink.selectedProductId === localProductLink.family.id
            ? null
            : localProductLink.selectedProductId
        );
        resolvedProductLinkKeyRef.current = productKey;
        return;
      }

      if (!productKey || resolvedProductLinkKeyRef.current === productKey) return;
      if (pendingProductLinkRef.current?.key === productKey) return;

      const expectedLocation = `${window.location.pathname}${window.location.hash}`;
      const request = (async () => {
        try {
          const publicProductLink = await fetchPublicProductLink(productKey);
          if (`${window.location.pathname}${window.location.hash}` !== expectedLocation) return;

          if (!publicProductLink) {
            setSelectedProductId(null);
            setSelectedProductVariantId(null);
            setLinkedProduct(null);
            showToast('هذا المنتج غير موجود أو لم يعد متاحًا للبيع.', 'info');
            return;
          }

          const selectedProduct = [
            publicProductLink.family,
            ...publicProductLink.family.variants,
          ].find((product) => product.id === publicProductLink.selectedProductId);
          if (!selectedProduct?.isAvailable) {
            setSelectedProductId(null);
            setSelectedProductVariantId(null);
            setLinkedProduct(null);
            showToast('هذا المنتج لم يعد متاحًا للبيع حاليًا.', 'info');
            return;
          }

          setLinkedProduct(publicProductLink.family);
          setSelectedProductId(publicProductLink.family.id);
          setSelectedProductVariantId(
            publicProductLink.selectedProductId === publicProductLink.family.id
              ? null
              : publicProductLink.selectedProductId
          );
        } catch {
          if (`${window.location.pathname}${window.location.hash}` === expectedLocation) {
            setSelectedProductId(null);
            setSelectedProductVariantId(null);
            setLinkedProduct(null);
            showToast('تعذر فتح هذا المنتج الآن. حاول مرة أخرى.', 'error');
          }
        }
      })();

      resolvedProductLinkKeyRef.current = productKey;
      pendingProductLinkRef.current = { key: productKey, promise: request };
      void request.finally(() => {
        if (pendingProductLinkRef.current?.promise === request) {
          pendingProductLinkRef.current = null;
        }
      });
    };

    syncProductFromLocation();
    window.addEventListener('hashchange', syncProductFromLocation);
    window.addEventListener('popstate', syncProductFromLocation);

    return () => {
      window.removeEventListener('hashchange', syncProductFromLocation);
      window.removeEventListener('popstate', syncProductFromLocation);
    };
  }, [products, showToast]);

  useEffect(() => {
    if (
      selectedCategory !== 'all' &&
      catalogCategories.length > 0 &&
      !catalogCategories.some((category) => category.id === selectedCategory)
    ) {
      setSelectedCategory('all');
    }
  }, [catalogCategories, selectedCategory]);

  useEffect(() => {
    const categorySlug = readStoreLocationRoute(window.location).categorySlug;
    if (!categorySlug || catalogCategories.length === 0) return;
    const category = catalogCategories.find(
      (candidate) => getCategorySlug(candidate) === categorySlug
    );
    setSelectedCategory(category?.id ?? 'all');
  }, [catalogCategories]);

  // Search, category, availability, brand, sale unit and sorting are all
  // applied by the catalog RPC over the complete catalog. The page only owns
  // rendering and the local favourites list.
  const filteredProducts = useMemo(
    () => products,
    [products]
  );

  const cartQuantityByProduct = useMemo(
    () => {
      const quantities = new Map<string, number>();
      for (const item of cartItems) {
        if (item.commercialLineKind !== 'legacy_single_sku_parcel') continue;
        quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
      }
      return quantities;
    },
    [cartItems]
  );
  const catalogCartQuantityByProduct = useMemo(
    () =>
      new Map(
        products.map((product) => [
          product.id,
          product.variants.length > 0
            ? product.variants.reduce(
                (sum, variant) =>
                  sum + (cartQuantityByProduct.get(variant.id) || 0),
                0
              )
            : cartQuantityByProduct.get(product.id) || 0,
        ] as const)
      ),
    [cartQuantityByProduct, products]
  );
  const resolvedFavoriteProductIds = useMemo(
    () =>
      new Set(
        products.flatMap((product) => [
          product.id,
          ...product.variants.map((variant) => variant.id),
        ])
      ),
    [products]
  );
  const missingFavoriteProductCount = useMemo(
    () =>
      favoriteProductIds.filter(
        (productId) => !resolvedFavoriteProductIds.has(productId)
      ).length,
    [favoriteProductIds, resolvedFavoriteProductIds]
  );
  const favoriteProducts = useMemo(
    () =>
      products.filter(
        (product) =>
          favoriteProductIds.includes(product.id) ||
          product.variants.some((variant) => favoriteProductIds.includes(variant.id))
      ),
    [favoriteProductIds, products]
  );
  const selectedProduct = useMemo(
    () =>
      products.find((product) => product.id === selectedProductId) ??
      linkedProduct ??
      null,
    [linkedProduct, products, selectedProductId]
  );
  const commerceReview = commerceSnapshot.reviewReason
    ? reviewPolicyFor(commerceSnapshot.reviewReason)
    : checkoutAttempt?.reviewRequired ?? null;
  const lockedLineIds = useMemo(
    () => new Set(
      unresolvedCheckoutAttempt && checkoutAttempt
        ? checkoutAttempt.submittedItems.map((item) => item.localLineId)
        : []
    ),
    [checkoutAttempt, unresolvedCheckoutAttempt]
  );
  const lockedParcelIds = useMemo(
    () => new Set(
      unresolvedCheckoutAttempt && checkoutAttempt
        ? checkoutAttempt.submittedItems.flatMap((item) =>
            item.commercialLineKind === 'configurable_parcel'
              ? item.parcelInstances.map((instance) => instance.localInstanceId)
              : []
          )
        : []
    ),
    [checkoutAttempt, unresolvedCheckoutAttempt]
  );
  const reservedBaseUnits = useMemo(
    () => requiredBaseUnitsByProductId(cartItems),
    [cartItems]
  );

  useEffect(() => {
    if (
      !selectedProduct ||
      parcelOptionsByFamily.has(selectedProduct.id) ||
      parcelOptionRequestedRef.current.has(selectedProduct.id)
    ) return;
    let active = true;
    parcelOptionRequestedRef.current.add(selectedProduct.id);
    setParcelOptionLoading(true);
    void fetchPublicConfigurableParcelOptions([selectedProduct.id])
      .then((response) => {
        if (!active) return;
        const option = response.guestCreationEnabled
          ? response.options.find((candidate) => candidate.familyProductId === selectedProduct.id)
          : undefined;
        if (option) {
          setParcelOptionsByFamily((current) => new Map(current).set(selectedProduct.id, option));
        }
      })
      .catch(() => undefined)
      .finally(() => { if (active) setParcelOptionLoading(false); });
    return () => { active = false; };
  }, [parcelOptionsByFamily, selectedProduct]);
  const relatedProducts = useMemo(() => {
    if (!selectedProduct) return [];
    return products
      .filter(
        (product) =>
          product.id !== selectedProduct.id &&
          product.categoryId === selectedProduct.categoryId
      )
      .slice(0, 4);
  }, [products, selectedProduct]);
  const cartPackages = calculateCartPackages(cartItems);
  const availablePackages = catalogSummary.availableSalePackages;
  const availableProductsCount = catalogSummary.availableProducts;
  const lowStockProductsCount = catalogSummary.lowStockProducts;
  const selectedCategoryDetails = catalogCategories.find(
    (category) => category.id === selectedCategory
  );
  const hasActiveCatalogView =
    Boolean(searchQuery.trim()) ||
    selectedCategory !== 'all' ||
    availabilityFilter !== 'all' ||
    sortOption !== 'recommended' ||
    selectedBrand !== 'all' ||
    selectedSaleUnit !== 'all';

  const brands = catalogBrands;
  const searchSuggestions = useMemo(
    () => (searchQuery.trim() ? products.slice(0, 5) : []),
    [products, searchQuery]
  );
  const newestProducts = featuredProducts.newest;
  const bestSellerProducts = featuredProducts.bestSellers;
  const offerProducts = featuredProducts.offers;
  const lowStockProducts = featuredProducts.lowStock;
  const cartSubtotal = calculateCartSubtotal(cartItems);
  const settingsTrusted = !settingsUnavailable && !isLoadingStorefrontSettings;
  const storeWhatsappUrl = buildWhatsAppUrl(storefrontSettings.whatsappNumber, `مرحبًا ${SEO_BRAND.officialName}، أريد الاستفسار عن أصناف الجملة.`);

  useStorefrontSeo({
    activePage,
    category: selectedCategoryDetails,
    product: selectedProduct,
    offers: storefrontOffers,
    privateState:
      cartOpen ||
      checkoutOpen ||
      trackingOpen ||
      Boolean(trackingToken) ||
      activePage === 'favorites' ||
      activePage === 'categories' ||
      Boolean(searchQuery.trim()),
  });

  useEffect(() => {
    if (!settingsTrusted && checkoutOpen) setCheckoutOpen(false);
  }, [checkoutOpen, settingsTrusted]);

  useEffect(() => {
    if (cartOpen || checkoutOpen || trackingOpen || privacyPolicyOpen) {
      setAssistantOpen(false);
    }
  }, [cartOpen, checkoutOpen, privacyPolicyOpen, trackingOpen]);

  const addQuantityToCart = (
    product: CatalogProduct,
    requestedQuantity = 1
  ) => {
    if (cartStorageRecovery) {
      setCartOpen(true);
      showToast('راجع حالة السلة المحفوظة قبل إضافة أصناف جديدة.', 'info');
      return;
    }
    if (!product.isAvailable) {
      showToast('هذا الصنف غير متوفر حاليًا.', 'error');
      return;
    }

    const remainingPackages = remainingStorefrontParcels(product, requiredBaseUnitsByProductId(cartItems).get(product.id) ?? 0);
    if (remainingPackages === 0) {
      showToast('وصلت إلى كامل الكمية المتاحة من هذا الصنف.', 'info');
      return;
    }

    const quantityToAdd = Math.min(
      remainingPackages,
      Math.max(1, Math.floor(requestedQuantity || 1))
    );

    let addedQuantity = 0;
    void mutateCart((currentItems) => {
      const actualQuantity = Math.min(quantityToAdd, remainingStorefrontParcels(product, requiredBaseUnitsByProductId(currentItems).get(product.id) ?? 0));
      if (actualQuantity === 0) return currentItems;
      addedQuantity = actualQuantity;
      const currentItem = currentItems.find(
        (item) =>
          item.productId === product.id &&
          item.commercialLineKind === 'legacy_single_sku_parcel' &&
          !lockedLineIds.has(item.localLineId)
      );
      if (!currentItem) {
        return [
          ...currentItems,
          { ...createCartItem(product), quantity: actualQuantity },
        ];
      }
      return currentItems.map((item) =>
        item.localLineId === currentItem.localLineId
          ? { ...item, quantity: item.quantity + actualQuantity }
          : item
      );
    }).then(() => {
      if (addedQuantity > 0) showToast(`تمت إضافة ${addedQuantity.toLocaleString('ar-JO')} ${storefrontSaleUnit(product)} من ${product.nameAr}.`);
      else showToast('وصلت السلة إلى كامل المخزون المتاح من هذا الصنف.', 'info');
    }).catch(() => showToast('تعذر حفظ الإضافة في السلة. راجع حالة السلة وحاول مجددًا.', 'error'));
  };

  const addToCart = (product: CatalogProduct) => {
    addQuantityToCart(product, 1);
  };

  const addBaseUnitToCart = (product: CatalogProduct, requestedQuantity = 1) => {
    if(product.parcelOnly){showToast('هذا الصنف بيتباع بالطرد بس؛ اختر طرداً.','info');return;}
    if (cartStorageRecovery) {
      setCartOpen(true);
      showToast('راجع حالة السلة المحفوظة قبل إضافة أصناف جديدة.', 'info');
      return;
    }
    if (product.salePriceInMinorUnits <= 0 || product.availableQuantity < 1) {
      showToast('هذا الباكيت غير متاح للبيع مفرداً حاليًا.', 'info');
      return;
    }
    const alreadyRequired = requiredBaseUnitsByProductId(cartItems).get(product.id) ?? 0;
    if (alreadyRequired >= product.availableQuantity) {
      showToast('وصلت السلة إلى كامل المخزون المتاح من هذه النكهة.', 'info');
      return;
    }
    const quantityToAdd = Math.min(product.availableQuantity - alreadyRequired, Math.max(1, Math.floor(requestedQuantity || 1)));
    let addedQuantity = 0;
    void mutateCart((current) => {
      const actualQuantity = Math.min(quantityToAdd, Math.max(0, product.availableQuantity - (requiredBaseUnitsByProductId(current).get(product.id) ?? 0)));
      if (actualQuantity === 0) return current;
      addedQuantity = actualQuantity;
      const existing = current.find(
        (item) =>
          item.commercialLineKind === 'base_unit' &&
          item.productId === product.id &&
          !lockedLineIds.has(item.localLineId)
      );
      if (!existing) return [...current, {...createBaseUnitCartItem(product), quantity: actualQuantity}];
      return current.map((item) => item.localLineId === existing.localLineId
        ? { ...item, localRevision: item.localRevision + 1, quantity: item.quantity + actualQuantity }
        : item);
    }).then(() => {
      if (addedQuantity > 0) showToast(`تمت إضافة ${addedQuantity.toLocaleString('ar-JO')} ${storefrontUnitName(product.unitNameAr)} من ${product.nameAr}.`);
      else showToast('وصلت السلة إلى كامل المخزون المتاح من هذا الصنف.', 'info');
    }).catch(() => showToast('تعذر حفظ الإضافة في السلة. راجع حالة السلة وحاول مجددًا.', 'error'));
  };

  const saveParcelBuilder = (instance: ParcelInstanceSelection) => {
    if (!parcelBuilder) return;
    if (cartStorageRecovery) {
      setParcelBuilder(null);
      setCartOpen(true);
      showToast('راجع حالة السلة المحفوظة قبل حفظ طرد جديد.', 'info');
      return;
    }
    setCartItems((current) => {
      if (parcelBuilder.edit) {
        return current.map((item) =>
          item.localLineId === parcelBuilder.edit?.lineId && item.commercialLineKind === 'configurable_parcel'
            ? replaceParcelInstance(item, parcelBuilder.edit.instance.localInstanceId, instance)
            : item
        );
      }
      const matchingLine = current.find(
        (item): item is ConfigurableParcelCartItem =>
          item.commercialLineKind === 'configurable_parcel' &&
          item.parcelConfigurationId === parcelBuilder.option.parcelConfigurationId &&
          item.configurationRevision === parcelBuilder.option.configurationRevision &&
          !lockedLineIds.has(item.localLineId)
      );
      if (matchingLine) {
        return current.map((item) => item.localLineId === matchingLine.localLineId
          ? {
              ...matchingLine,
              localRevision: matchingLine.localRevision + 1,
              quantity: matchingLine.parcelInstances.length + 1,
              parcelInstances: [...matchingLine.parcelInstances, instance],
            }
          : item);
      }
      return [...current, createConfigurableParcelCartItem(
        parcelBuilder.familyProduct,
        parcelBuilder.option,
        instance
      )];
    });
    setParcelBuilder(null);
    showToast('تم حفظ الطرد بالنكهات في السلة.');
  };

  const editParcelInstance = (lineId: string, instance: ParcelInstanceSelection) => {
    if (lockedParcelIds.has(instance.localInstanceId)) {
      showToast('هذا الطرد مرتبط بطلب غير محسوم ولا يمكن تعديله الآن.', 'info');
      return;
    }
    const line = cartItems.find(
      (item): item is ConfigurableParcelCartItem => item.localLineId === lineId && item.commercialLineKind === 'configurable_parcel'
    );
    const familyProduct = products.find((product) => product.id === line?.familyProductId);
    const option = line ? parcelOptionsByFamily.get(line.familyProductId) : undefined;
    if (!line || !familyProduct || !option) {
      showToast('تعذر تحميل إعداد الطرد الحالي. أعد فتح المنتج.', 'error');
      return;
    }
    setParcelBuilder({ familyProduct, option, edit: { lineId, instance } });
  };

  const duplicateParcel = (lineId: string, instance: ParcelInstanceSelection) => {
    if (cartStorageRecovery) return;
    const line = cartItems.find(
      (item): item is ConfigurableParcelCartItem => item.localLineId === lineId && item.commercialLineKind === 'configurable_parcel'
    );
    if (!line) return;
    const duplicate = duplicateParcelInstance(instance);
    const requirements = requiredBaseUnitsByProductId(cartItems);
    const option = parcelOptionsByFamily.get(line.familyProductId);
    const unavailable = duplicate.components.some((component) => {
      const available = option?.components.find((candidate) => candidate.productId === component.productId)?.availableQuantity ?? 0;
      return (requirements.get(component.productId) ?? 0) + component.baseQuantity > available;
    });
    if (unavailable) {
      showToast('لا يكفي المخزون الحالي لتكرار هذا الطرد.', 'info');
      return;
    }
    setCartItems((current) => {
      if (lockedLineIds.has(lineId)) {
        const familyProduct = products.find((product) => product.id === line.familyProductId);
        if (!familyProduct || !option) return current;
        return [...current, createConfigurableParcelCartItem(familyProduct, option, duplicate)];
      }
      return current.map((item) => item.localLineId === lineId && item.commercialLineKind === 'configurable_parcel'
        ? { ...item, localRevision: item.localRevision + 1, quantity: item.parcelInstances.length + 1, parcelInstances: [...item.parcelInstances, duplicate] }
        : item);
    });
  };

  const removeParcel = (lineId: string, instanceId: string) => {
    if (cartStorageRecovery) return;
    if (lockedParcelIds.has(instanceId)) {
      showToast('هذا الطرد مرتبط بطلب غير محسوم ولا يمكن حذفه الآن.', 'info');
      return;
    }
    setCartItems((current) => current.flatMap((item) => {
      if (item.localLineId !== lineId || item.commercialLineKind !== 'configurable_parcel') return [item];
      const next = removeParcelInstance(item, instanceId);
      return next ? [next] : [];
    }));
  };

  const refreshCartSnapshot = useCallback(async (
    itemsToRefresh: CartItem[] = cartItems
  ): Promise<CartSnapshotResult> => {
    if (cartStorageRecovery) {
      throw new Error('السلة المحفوظة تحتاج معالجة قبل تحديث السعر أو المخزون.');
    }
    if (unresolvedCheckoutAttempt) {
      throw new Error('يوجد طلب غير محسوم. أكمل استرداده قبل تحديث السلة أو بدء طلب جديد.');
    }
    const expectedCartRevision = commerceSnapshot.cart.envelope?.revision;
    const snapshotProductIds = Array.from(
      new Set(itemsToRefresh
        .filter((item) => item.commercialLineKind !== 'configurable_parcel')
        .map((item) => item.productId)
        .filter(Boolean))
    );
    const parcelFamilyIds = Array.from(new Set(itemsToRefresh.flatMap((item) =>
      item.commercialLineKind === 'configurable_parcel' ? [item.familyProductId] : []
    )));
    if (snapshotProductIds.length === 0 && parcelFamilyIds.length === 0) return { items: [] };

    const snapshotKey = [...snapshotProductIds, ...parcelFamilyIds].sort().join(',');
    if (pendingCartSnapshotRef.current?.key === snapshotKey) {
      return pendingCartSnapshotRef.current.promise;
    }

    const request = (async () => {
      setIsRefreshingCart(true);
      try {
        const [snapshotProducts, parcelResponse] = await Promise.all([
          snapshotProductIds.length > 0 ? fetchPublicCartSnapshot(snapshotProductIds) : Promise.resolve([]),
          parcelFamilyIds.length > 0
            ? fetchPublicConfigurableParcelOptions(parcelFamilyIds)
            : Promise.resolve(null),
        ]);
        const reconciliation = reconcileCartSnapshot(
          itemsToRefresh,
          snapshotProducts,
          snapshotProductIds
        );
        const optionByFamily = new Map(parcelResponse?.options.map((option) => [option.familyProductId, option]) ?? []);
        const parcelItems = reconciliation.items.map((item) => {
          if (item.commercialLineKind !== 'configurable_parcel') return item;
          const option = optionByFamily.get(item.familyProductId);
          if (
            !parcelResponse?.guestCreationEnabled ||
            !option ||
            option.parcelConfigurationId !== item.parcelConfigurationId ||
            option.configurationRevision !== item.configurationRevision ||
            option.unitsPerParcel !== item.capacity
          ) {
            throw new Error('تغيّر إعداد أحد الطرود. افتح المنتج وراجع تكوينه قبل المتابعة.');
          }
          return {
            ...item,
            unitPriceInMinorUnits: option.parcelPriceInMinorUnits,
            saleUnitNameAr: option.saleUnitNameAr,
          };
        });
        const required = requiredBaseUnitsByProductId(parcelItems);
        for (const option of parcelResponse?.options ?? []) {
          for (const component of option.components) {
            if ((required.get(component.productId) ?? 0) > component.availableQuantity) {
              throw new Error(`الكمية المطلوبة من ${component.flavorNameAr || component.nameAr} لم تعد متاحة.`);
            }
          }
        }
        const persistedItems = await mutateCart((currentItems) =>
          reconcileCartSnapshot(
            currentItems,
            snapshotProducts,
            snapshotProductIds
          ).items.map((item) => {
            if (item.commercialLineKind !== 'configurable_parcel') return item;
            const option = optionByFamily.get(item.familyProductId);
            return option && option.configurationRevision === item.configurationRevision
              ? { ...item, unitPriceInMinorUnits: option.parcelPriceInMinorUnits, saleUnitNameAr: option.saleUnitNameAr }
              : item;
          }),
          expectedCartRevision
        );

        const notices: string[] = [];
        if (reconciliation.priceChanges > 0) {
          notices.push('تم تحديث سعر بعض الأصناف.');
        }
        if (reconciliation.quantityAdjustments > 0) {
          notices.push('تم تعديل الكمية إلى المتاح حاليًا.');
        }
        if (reconciliation.removedUnavailableItems > 0) {
          notices.push('تمت إزالة أصناف لم تعد متاحة للبيع.');
        }
        setCartSnapshotNotice(notices.length > 0 ? notices.join(' ') : null);
        return { items: persistedItems };
      } finally {
        setIsRefreshingCart(false);
      }
    })();

    pendingCartSnapshotRef.current = { key: snapshotKey, promise: request };
    try {
      return await request;
    } finally {
      if (pendingCartSnapshotRef.current?.promise === request) {
        pendingCartSnapshotRef.current = null;
      }
    }
  }, [cartItems, cartStorageRecovery, commerceSnapshot.cart.envelope?.revision, mutateCart, unresolvedCheckoutAttempt]);

  const openCart = useCallback((itemsToRefresh?: CartItem[]) => {
    setCartOpen(true);
    if (cartStorageRecovery) return;
    void refreshCartSnapshot(itemsToRefresh).catch((error: unknown) => {
      const message = error instanceof Error
        ? error.message
        : 'تعذر التحقق من سعر ومخزون السلة. حاول مرة أخرى.';
      setCartSnapshotNotice(message);
    });
  }, [cartStorageRecovery, refreshCartSnapshot]);

  const openProductDetails = useCallback((product: CatalogProduct) => {
    setLinkedProduct(null);
    setSelectedProductId(product.id);
    setSelectedProductVariantId(null);
    const nextPath = getProductPath(product.sku || product.id);
    if (window.location.pathname === nextPath && !window.location.hash) return;
    changeStoreLocation(nextPath, window.location.pathname.startsWith('/product/'));
  }, []);

  const closeProductDetails = useCallback(() => {
    setSelectedProductId(null);
    setSelectedProductVariantId(null);
    setLinkedProduct(null);
    if (readStoreLocationRoute(window.location).productKey) {
      const nextPath = selectedCategoryDetails
        ? getCategoryPath(getCategorySlug(selectedCategoryDetails))
        : getStorePagePath(activePage);
      changeStoreLocation(nextPath, true);
    }
  }, [activePage, selectedCategoryDetails]);

  const updateCartQuantity = (localLineId: string, quantity: number) => {
    if (cartStorageRecovery) return;
    if (lockedLineIds.has(localLineId)) {
      showToast('هذا السطر مرتبط بطلب غير محسوم. أضف كمية جديدة كسطر مستقل.', 'info');
      return;
    }
    if (quantity <= 0) {
      setCartItems((items) =>
        items.filter((item) => item.localLineId !== localLineId)
      );
      return;
    }

    setCartItems((items) =>
      items.map((item) =>
        item.localLineId === localLineId && item.commercialLineKind !== 'configurable_parcel'
          ? {
              ...item,
              localRevision: item.localRevision + 1,
              quantity: Math.min(
                Math.max(1, Math.floor(quantity)),
                item.maxAvailablePackages
              ),
            }
          : item
      )
    );
  };

  // Catalogue counters aggregate legacy parcels;the cart writer takes a line ID.
  // Resolve only an editable parcel line,never a base-unit or frozen line.
  const updateCatalogCartQuantity = (productId: string, quantity: number) => {
    if (cartStorageRecovery) return;
    const currentQuantity = cartQuantityByProduct.get(productId) ?? 0;
    if (quantity > currentQuantity) {
      const product = sellableProducts.find(candidate => candidate.id === productId);
      if (product) addQuantityToCart(product, quantity - currentQuantity);
      return;
    }
    if (quantity >= currentQuantity) return;
    const line = cartItems.find(item => item.productId === productId
      && item.commercialLineKind === 'legacy_single_sku_parcel'
      && !lockedLineIds.has(item.localLineId));
    if (!line) {
      showToast('الكمية مرتبطة بطلب غير محسوم ولا يمكن إنقاصها الآن.', 'info');
      return;
    }
    updateCartQuantity(line.localLineId, Math.max(0, line.quantity - (currentQuantity - quantity)));
  };

  const resetCatalogView = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setAvailabilityFilter('all');
    setSortOption('recommended');
    setSelectedBrand('all');
    setSelectedSaleUnit('all');
    setCatalogOffset(0);
  };

  const navigateStorePage = useCallback((page: StorePage) => {
    setActivePage(page);
    changeStoreLocation(getStorePagePath(page));
    window.requestAnimationFrame(() => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }, []);

  const scrollToCatalog = () => {
    setActivePage('catalog');
    changeStoreLocation(getStorePagePath('catalog'));
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        document.getElementById('catalog-products')?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      });
    });
  };

  const showAllProducts = () => {
    resetCatalogView();
    scrollToCatalog();
  };

  const openFavorites = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setAvailabilityFilter('all');
    setSortOption('recommended');
    setSelectedBrand('all');
    setSelectedSaleUnit('all');
    setCatalogOffset(0);
    navigateStorePage('favorites');
  };

  const toggleProductFavorite = (product: CatalogProduct) => {
    setFavoriteProductIds((current) => {
      const isFavorite = current.includes(product.id);
      showToast(
        isFavorite
          ? `تمت إزالة ${product.nameAr} من المفضلة.`
          : `تمت إضافة ${product.nameAr} إلى المفضلة.`
      );
      return isFavorite
        ? current.filter((productId) => productId !== product.id)
        : [...current, product.id];
    });
