                  <div
                    data-testid="favorites-empty-state"
                    className="mt-7 rounded-[1.75rem] border border-dashed border-rose-200 bg-rose-50/50 px-5 py-12 text-center"
                  >
                    <div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-white text-rose-500 shadow-sm">
                      <Heart className="h-6 w-6" />
                    </div>
                    <h3 className="mt-5 text-lg font-black text-slate-900">
                      مفضلتك فارغة حاليًا
                    </h3>
                    <p className="mx-auto mt-2 max-w-md text-xs leading-6 text-slate-500">
                      أضف المنتجات التي تهمك عبر رمز القلب لتجدها هنا بسرعة.
                    </p>
                    <button
                      type="button"
                      onClick={showAllProducts}
                      className="mt-6 inline-flex min-h-11 items-center justify-center rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white transition hover:bg-blue-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700"
                    >
                      تصفح المنتجات
                    </button>
                  </div>
                ) : isLoading ? (
                  <div className="mt-7 grid grid-cols-2 gap-3 min-[380px]:grid-cols-3 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4">
                    {Array.from({ length: Math.min(4, favoriteProductIds.length) }).map((_, index) => (
                      <div
                        key={index}
                        className="h-[430px] animate-pulse rounded-[1.75rem] border border-slate-200 bg-slate-50 p-4"
                      >
                        <div className="h-52 rounded-3xl bg-slate-100" />
                        <div className="mt-5 h-4 w-2/3 rounded bg-slate-100" />
                        <div className="mt-3 h-3 w-1/3 rounded bg-slate-100" />
                      </div>
                    ))}
                  </div>
                ) : loadError && favoriteProducts.length === 0 ? (
                  <div className="mt-7 rounded-[1.75rem] border border-rose-200 bg-rose-50/50 p-8 text-center">
                    <AlertTriangle className="mx-auto h-9 w-9 text-rose-500" />
                    <h3 className="mt-4 text-base font-black text-slate-900">
                      تعذر تحديث المفضلة الآن
                    </h3>
                    <p className="mx-auto mt-2 max-w-md text-xs leading-6 text-slate-500">
                      لم نعرض معلومات قديمة عن السعر أو التوفر. حاول مرة أخرى.
                    </p>
                    <button
                      type="button"
                      onClick={() => void loadCatalog(false, true)}
                      className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white"
                    >
                      <RefreshCw className="h-4 w-4" />
                      إعادة المحاولة
                    </button>
                  </div>
                ) : favoriteProducts.length === 0 ? (
                  <div className="mt-7 rounded-[1.75rem] border border-amber-200 bg-amber-50/60 p-8 text-center">
                    <AlertTriangle className="mx-auto h-9 w-9 text-amber-600" />
                    <h3 className="mt-4 text-base font-black text-slate-900">
                      لا توجد منتجات مفضلة قابلة للعرض الآن
                    </h3>
                    <p className="mx-auto mt-2 max-w-md text-xs leading-6 text-slate-600">
                      قد تكون بعض المنتجات قد حُذفت أو لم تعد متاحة للبيع. أبقينا قائمتك محفوظة كما هي.
                    </p>
                    <button
                      type="button"
                      onClick={showAllProducts}
                      className="mt-5 inline-flex min-h-11 items-center justify-center rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white"
                    >
                      تصفح المنتجات
                    </button>
                  </div>
                ) : (
                  <>
                    {missingFavoriteProductCount > 0 && (
                      <div className="mt-6 flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs leading-6 text-amber-900">
                        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-700" />
                        <p>
                          بعض العناصر المحفوظة لم تعد متاحة للعرض حاليًا. أبقيناها في قائمتك ولم نحذفها تلقائيًا.
                        </p>
                      </div>
                    )}
                    <div
                      data-testid="favorites-products-grid"
                      className="mt-7 grid grid-cols-2 gap-3 min-[380px]:grid-cols-3 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4"
                    >
                      {favoriteProducts.map((product) => (
                        <ProductCard
                          key={product.id}
                          product={product}
                          cartQuantity={catalogCartQuantityByProduct.get(product.id) || 0}
                          reservedQuantity={reservedBaseUnits.get(product.id) ?? 0}
                          isFavorite={favoriteProductIds.includes(product.id)}
                          onAdd={addToCart}
                          onQuantityChange={updateCatalogCartQuantity}
                          onOpenDetails={openProductDetails}
                          onToggleFavorite={toggleProductFavorite}
                        />
                      ))}
                    </div>
                  </>
                )}
              </div>
            </div>
          </section>
        )}

        {activePage === 'home' && (
          <>
        <section className="border-y border-slate-200 bg-white py-12">
          <div className="mx-auto grid max-w-7xl gap-4 px-4 sm:grid-cols-3 lg:px-8">
            {[
              {
                icon: ShieldCheck,
                title: 'أسعار آمنة',
                text: 'الموقع يعرض سعر البيع فقط ولا يكشف تكلفة الشراء.',
              },
              {
                icon: Boxes,
                title: 'طرد أو باكيت',
                text: 'اختر الطرد أو الباكيت؛ أساس الكمية والسعر واضح بجانب كل زر.',
              },
              {
                icon: Truck,
                title: 'مخزون موحّد',
                text: 'إضافة المنتج وتعديل سعره من الإدارة ينعكسان على الكتالوج.',
              },
            ].map((benefit) => {
              const Icon = benefit.icon;
              return (
                <div
                  key={benefit.title}
                  className="flex items-start gap-3 rounded-3xl bg-slate-50 p-5"
                >
                  <div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-blue-100 text-blue-700">
                    <Icon className="h-5 w-5" />
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-slate-900">
                      {benefit.title}
                    </h3>
                    <p className="mt-1 text-[11px] leading-5 text-slate-500">
                      {benefit.text}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
          </>
        )}
      </main>

      <CategoryDrawer
        isOpen={categoriesOpen}
        categories={catalogCategories}
        selectedCategory={selectedCategory}
                totalProducts={catalogTotal}
        onClose={() => setCategoriesOpen(false)}
        onSelect={selectCatalogCategory}
      />

      <StoreFooter
        whatsappUrl={storeWhatsappUrl}
        onNavigate={navigateStorePage}
        onTrackOrder={() => setTrackingOpen(true)}
        onOpenPrivacy={() => setPrivacyPolicyOpen(true)}
      />

      {selectedProduct && (
        <ProductDetailsModal
          product={selectedProduct}
          initialVariantId={selectedProductVariantId ?? undefined}
          cartQuantityByProduct={cartQuantityByProduct}
          reservedBaseUnits={reservedBaseUnits}
          relatedProducts={relatedProducts}
          onClose={closeProductDetails}
          onAddQuantity={addQuantityToCart}
          onAddBaseUnit={addBaseUnitToCart}
          parcelOption={parcelOptionsByFamily.get(selectedProduct.id)}
          parcelOptionLoading={parcelOptionLoading}
          onOpenParcelBuilder={(familyProduct, option) =>
            setParcelBuilder({ familyProduct, option })
          }
          onOpenProduct={openProductDetails}
          storeWhatsAppNumber={storefrontSettings.whatsappNumber}
          isFavorite={favoriteProductIds.includes(selectedProduct.id)}
          onToggleFavorite={toggleProductFavorite}
          onOpenAssistant={() => setAssistantOpen(true)}
        />
      )}

      <GuidedStoreAssistant
        isOpen={assistantOpen}
        showFloatingButton={
          !selectedProduct &&
          !cartOpen &&
          !checkoutOpen &&
          !trackingOpen &&
          !privacyPolicyOpen
        }
        settings={settingsTrusted ? storefrontSettings : null}
        whatsappUrl={storeWhatsappUrl}
        onOpen={() => setAssistantOpen(true)}
        onClose={() => setAssistantOpen(false)}
        onBrowseProducts={showAllProducts}
        onOpenOffers={openPromotionOffers}
        onTrackOrder={() => setTrackingOpen(true)}
        hasCartItems={cartPackages > 0}
      />

      <CartDrawer
        isOpen={cartOpen}
        items={cartItems}
        onClose={() => setCartOpen(false)}
        onQuantityChange={updateCartQuantity}
        onRemove={(localLineId) =>
          !cartStorageRecovery &&
          !lockedLineIds.has(localLineId) &&
          setCartItems((items) =>
            items.filter((item) => item.localLineId !== localLineId)
          )
        }
        onEditParcel={editParcelInstance}
        onDuplicateParcel={duplicateParcel}
        onRemoveParcel={removeParcel}
        lockedParcelInstanceIds={lockedParcelIds}
        lockedLineIds={lockedLineIds}
        cartStorageRecovery={cartStorageRecovery}
        hasUnresolvedCheckoutAttempt={unresolvedCheckoutAttempt}
        onResolveCartRecovery={handleCartStorageRecovery}
        onClear={() => {
          if (cartStorageRecovery) {
            showToast('استخدم إجراء معالجة السلة بدل الحذف التلقائي.', 'info');
            return;
          }
          if (lockedLineIds.size > 0 || lockedParcelIds.size > 0) {
            showToast('لا يمكن إفراغ السلة قبل حسم محاولة الطلب الحالية.', 'info');
            return;
          }
          setCartItems([]);
        }}
        onCheckout={openCheckout}
        isRefreshingSnapshot={isRefreshingCart}
        snapshotNotice={cartSnapshotNotice}
        checkoutDisabled={!settingsTrusted || Boolean(cartStorageRecovery) || Boolean(commerceReview)}
        checkoutBlockedMessage={
          commerceReview
            ? commerceReview.message
            : cartStorageRecovery
            ? 'السلة المحفوظة تحتاج معالجة صريحة قبل إتمام الطلب.'
            : settingsUnavailable
            ? 'تعذر التحقق من إعدادات الطلب والتوصيل. لن نعرض رسومًا أو حدًا أدنى غير موثوقين.'
            : 'جارٍ التحقق من إعدادات الطلب والتوصيل.'
        }
        onRetryCheckoutSettings={
          settingsUnavailable
            ? () => void loadStorefrontSettings(true)
            : undefined
        }
      />

      <CheckoutModal
        isOpen={checkoutOpen}
        items={cartItems}
        storeWhatsAppNumber={storefrontSettings.whatsappNumber}
        storefrontSettings={storefrontSettings}
        settingsUnavailable={settingsUnavailable}
        initialPromotionCode={preferredPromotionCode}
        coordinator={checkoutCoordinator}
        onClose={() => setCheckoutOpen(false)}
        onRetryStorefrontSettings={() => void loadStorefrontSettings(true)}
        onOpenPrivacyPolicy={() => setPrivacyPolicyOpen(true)}
        onOrderCreated={handleOrderCreated}
        onTrackOrder={openCreatedOrderTracking}
      />

      {parcelBuilder && (
        <ParcelBuilderModal
          option={parcelBuilder.option}
          initialInstance={parcelBuilder.edit?.instance}
          reservedByProductId={reservedBaseUnits}
          onClose={() => setParcelBuilder(null)}
          onSave={saveParcelBuilder}
        />
      )}

      <OrderTrackingModal
        isOpen={trackingOpen}
        trackingToken={trackingToken}
        onClose={() => {
          setTrackingOpen(false);
          if (trackingToken) {
            window.history.replaceState(null, '', '/');
            window.dispatchEvent(new PopStateEvent('popstate'));
          }
        }}
      />

      <PrivacyPolicyModal
        isOpen={privacyPolicyOpen}
        onClose={() => setPrivacyPolicyOpen(false)}
        storeName={SEO_BRAND.officialName}
        whatsappNumber={storefrontSettings.whatsappNumber}
      />

      <MobileStoreNav cartPackages={cartPackages} cartSummary={formatCartQuantitySummary(cartItems)} cartTotal={cartSubtotal} whatsappUrl={storeWhatsappUrl} onHome={() => navigateStorePage('home')} onCategories={() => navigateStorePage('categories')} onSearch={() => { setActivePage('catalog'); changeStoreLocation(getStorePagePath('catalog')); setSearchOpenSignal((value) => value + 1); }} onCart={() => openCart()} />

      <FloatingContactActions whatsappUrl={storeWhatsappUrl} />

      {toast && (
        <div
          className={`fixed bottom-5 left-1/2 z-[70] flex -translate-x-1/2 items-center gap-2 rounded-2xl px-4 py-3 text-xs font-extrabold text-white shadow-2xl ${
            toast.type === 'error'
              ? 'bg-rose-600'
              : toast.type === 'info'
              ? 'bg-slate-800'
              : 'bg-emerald-600'
          }`}
        >
          {toast.type === 'error' ? (
            <AlertTriangle className="h-4 w-4" />
          ) : (
            <CheckCircle2 className="h-4 w-4" />
          )}
          {toast.message}
        </div>
      )}
    </div>
  );
}

customer-web/src/components/CartDrawer.t.beforeText:
import {storefrontCartPackageDescription} from '../utils/storefrontUnits';
import {
  AlertTriangle,
  ArrowLeft,
  Copy,
  Pencil,
  LockKeyhole,
  Minus,
  Plus,
  ShoppingBag,
  TicketPercent,
  Trash2,
  X,
} from 'lucide-react';
import { useEffect, useState } from 'react';
import { CartItem, ParcelInstanceSelection } from '../types/catalog';
import { formatCartQuantitySummary, calculateCartSubtotal } from '../utils/cart';
import { CartStorageRecovery } from '../utils/cart';
import { formatJod } from '../utils/money';
import { CheckoutProgress } from './CheckoutProgress';
import { ProductImage } from './ProductImage';
import {useDialogFocus} from '../hooks/useDialogFocus';

interface CartDrawerProps {
  isOpen: boolean;
  items: CartItem[];
  onClose: () => void;
  onQuantityChange: (localLineId: string, quantity: number) => void;
  onRemove: (localLineId: string) => void;
  onEditParcel: (lineId: string, instance: ParcelInstanceSelection) => void;
  onDuplicateParcel: (lineId: string, instance: ParcelInstanceSelection) => void;
  onRemoveParcel: (lineId: string, instanceId: string) => void;
  lockedParcelInstanceIds: ReadonlySet<string>;
  lockedLineIds: ReadonlySet<string>;
  cartStorageRecovery?: CartStorageRecovery | null;
  hasUnresolvedCheckoutAttempt?: boolean;
  onResolveCartRecovery?: () => void;
  onClear: () => void;
  onCheckout: () => void;
  isRefreshingSnapshot?: boolean;
  snapshotNotice?: string | null;
  checkoutDisabled?: boolean;
  checkoutBlockedMessage?: string;
  onRetryCheckoutSettings?: () => void;
}

export function CartDrawer({
  isOpen,
  items,
  onClose,
  onQuantityChange,
  onRemove,
  onEditParcel,
  onDuplicateParcel,
  onRemoveParcel,
  lockedParcelInstanceIds,
  lockedLineIds,
  cartStorageRecovery,
  hasUnresolvedCheckoutAttempt = false,
  onResolveCartRecovery,
  onClear,
  onCheckout,
  isRefreshingSnapshot = false,
  snapshotNotice,
  checkoutDisabled = false,
  checkoutBlockedMessage,
  onRetryCheckoutSettings,
}: CartDrawerProps) {
  const [clearConfirmationOpen, setClearConfirmationOpen] = useState(false);
  const panel = useDialogFocus(isOpen, () => {
    if (clearConfirmationOpen) setClearConfirmationOpen(false);
    else onClose();
  });
  const quantitySummary = formatCartQuantitySummary(items);
  const subtotal = calculateCartSubtotal(items);

  useEffect(() => {
    if (!isOpen) setClearConfirmationOpen(false);
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const scrollY = window.scrollY;
    const body = document.body;
    const root = document.documentElement;
    const previousBodyStyles = {
      overflow: body.style.overflow,
      position: body.style.position,
      top: body.style.top,
      width: body.style.width,
      overscrollBehavior: body.style.overscrollBehavior,
    };
    const previousRootStyles = {
      overflow: root.style.overflow,
      overscrollBehavior: root.style.overscrollBehavior,
    };

    body.style.overflow = 'hidden';
    body.style.position = 'fixed';
    body.style.top = `-${scrollY}px`;
    body.style.width = '100%';
    body.style.overscrollBehavior = 'none';
    root.style.overflow = 'hidden';
    root.style.overscrollBehavior = 'none';

    return () => {
      body.style.overflow = previousBodyStyles.overflow;
      body.style.position = previousBodyStyles.position;
      body.style.top = previousBodyStyles.top;
      body.style.width = previousBodyStyles.width;
      body.style.overscrollBehavior = previousBodyStyles.overscrollBehavior;
      root.style.overflow = previousRootStyles.overflow;
      root.style.overscrollBehavior = previousRootStyles.overscrollBehavior;
      window.scrollTo({ top: scrollY, behavior: 'auto' });
    };
  }, [isOpen]);

  const handleConfirmedClear = () => {
    onClear();
    setClearConfirmationOpen(false);
  };

  return (
    <div
      className={`fixed inset-0 z-50 isolate overflow-hidden overscroll-none transition ${
        isOpen ? 'pointer-events-auto' : 'pointer-events-none'
      }`}
      aria-hidden={!isOpen}
      inert={!isOpen}
    >
      <button
        type="button"
        aria-label="إغلاق السلة"
        onClick={onClose}
        className={`absolute inset-0 bg-slate-950/55 backdrop-blur-sm transition-opacity ${
          isOpen ? 'opacity-100' : 'opacity-0'
        }`}
      />

      <aside
        ref={panel}
        tabIndex={-1}
        role="dialog"
        aria-modal="true"
        aria-labelledby="cart-drawer-title"
        className={`absolute inset-0 flex h-[100dvh] max-h-[100dvh] w-full flex-col overflow-hidden overscroll-none bg-white shadow-2xl transition-transform duration-300 sm:inset-y-0 sm:left-0 sm:right-auto sm:h-full sm:max-h-none sm:max-w-2xl ${
          isOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        <div className="shrink-0 flex items-center justify-between border-b border-slate-100 px-4 py-3 sm:px-5 sm:py-4">
          <div className="flex items-center gap-3">
            <div className="grid h-10 w-10 place-items-center rounded-2xl bg-blue-100 text-blue-700">
              <ShoppingBag className="h-5 w-5" />
            </div>
            <div>
              <h2 id="cart-drawer-title" className="font-black text-slate-950">سلة طلب الجملة</h2>
              <p className="text-[10px] font-bold text-slate-400">
                {quantitySummary}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="إغلاق"
            className="grid h-11 w-11 place-items-center rounded-xl bg-slate-100 text-slate-500"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {cartStorageRecovery && (
          <div
            role="alert"
            data-cart-storage-recovery
            className="border-b border-amber-200 bg-amber-50 p-4 text-right"
          >
            <div className="flex items-start gap-2 text-amber-950">
              <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0" />
              <div className="min-w-0 flex-1">
                <strong className="block text-xs font-black">
                  السلة المحفوظة تحتاج مراجعة
                </strong>
                <p className="mt-1 text-[10px] font-bold leading-5 text-amber-800">
                  لم نحذف أو نصلح أي بيانات تلقائيًا. عُثر على{' '}
                  {cartStorageRecovery.invalidEntries.length || 1} جزء غير صالح،
                  وإتمام الطلب متوقف لحماية محتوى السلة.
                </p>
                {hasUnresolvedCheckoutAttempt && (
                  <p className="mt-2 text-[10px] font-black text-blue-800">
                    محاولة الطلب غير المحسومة محفوظة بصورة مستقلة ولن تتغير عند معالجة السلة.
                  </p>
                )}
                {cartStorageRecovery.originalRaw === null && (
                  <p className="mt-2 text-[10px] font-black text-rose-700">
                    تعذر الوصول إلى تخزين المتصفح. تحقق من إعداداته ثم أعد تحميل الصفحة.
                  </p>
                )}
                {onResolveCartRecovery && (
                  <button
                    type="button"
                    onClick={onResolveCartRecovery}
                    disabled={cartStorageRecovery.originalRaw === null}
                    className="mt-3 min-h-11 rounded-xl bg-amber-900 px-4 py-2 text-[10px] font-black text-white disabled:cursor-not-allowed disabled:bg-slate-300"
                  >
                    {cartStorageRecovery.validItems.length > 0
                      ? 'أوافق على الاحتفاظ بالعناصر السليمة'
                      : 'أوافق على إعادة ضبط السلة'}
                  </button>
                )}
              </div>
            </div>
          </div>
        )}

        {items.length > 0 && (
          <div className="border-b border-slate-100 bg-gradient-to-b from-white to-slate-50">
            <CheckoutProgress currentStep={1} compact />
          </div>
        )}

        {items.length === 0 ? (
          <div className="grid flex-1 place-items-center p-8 text-center">
            <div>
              <div className="mx-auto grid h-20 w-20 place-items-center rounded-[2rem] bg-blue-50 text-blue-600">
                <ShoppingBag className="h-8 w-8" />
              </div>
              <h3 className="mt-5 font-black text-slate-900">السلة فارغة</h3>
              <p className="mt-2 text-xs leading-6 text-slate-500">
                أضف صنفًا من الكتالوج وسيبقى محفوظًا على هذا الجهاز.
              </p>
              <button
                type="button"
                onClick={onClose}
                className="mt-5 flex min-h-11 items-center justify-center rounded-2xl bg-blue-700 px-5 py-3 text-xs font-black text-white"
              >
                تصفح الأصناف
              </button>
            </div>
          </div>
        ) : (
          <>
            <div
              data-cart-scroll-region
              className="min-h-0 flex-1 touch-pan-y space-y-3 overflow-y-auto overscroll-contain p-4 [-webkit-overflow-scrolling:touch]"
            >
              {clearConfirmationOpen ? (
                <div className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-rose-200 bg-rose-50 p-3">
                  <p className="text-[10px] font-black text-rose-800">
                    هل أنت متأكد من حذف جميع الأصناف من السلة؟
                  </p>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={() => setClearConfirmationOpen(false)}
                      className="flex min-h-11 items-center rounded-xl border border-slate-200 bg-white px-3 py-1.5 text-[10px] font-black text-slate-600"
                    >
                      تراجع
                    </button>
                    <button
                      type="button"
                      onClick={handleConfirmedClear}
                      className="flex min-h-11 items-center rounded-xl bg-rose-600 px-3 py-1.5 text-[10px] font-black text-white"
                    >
                      نعم، إفراغ
                    </button>
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-between px-1">
                  <p className="text-[10px] font-bold text-slate-400">
                    الأسعار والكميات تُراجع تلقائيًا مع المخزون
                  </p>
                  <button
                    type="button"
                    onClick={() => setClearConfirmationOpen(true)}
                    className="flex min-h-11 items-center gap-1 px-2 text-[10px] font-extrabold text-rose-500"
                  >
                    <Trash2 className="h-3 w-3" />
                    إفراغ السلة
                  </button>
                </div>
              )}

              {items.map((item) => {
                const lineLocked = lockedLineIds.has(item.localLineId) || (
                  item.commercialLineKind === 'configurable_parcel' &&
                  item.parcelInstances.some((instance) => lockedParcelInstanceIds.has(instance.localInstanceId))
                );
                return (
                <article
                  key={item.localLineId}
